from cache import make_key, score

def test_make_key_uniqueness():
    assert make_key("a", "b", "c") != make_key("a", "b", "d")
    assert make_key("a", "b", "c") != make_key("a", "d", "c")
    assert make_key("a", "b", "c") != make_key("d", "b", "c")
    assert make_key("a", "b", "c") != make_key("a", "b", "c")

def test_make_key_separator():
    key = make_key("text", "profile", "criteria")
    assert "|" in key

def test_score_caching():
    store = {}
    def compute():
        return 42
    assert score(store, "text", "profile", "criteria", compute) == 42
    assert store == {"text|profile|criteria": 42}
    assert score(store, "text", "profile", "criteria", compute) == 42
    assert store == {"text|profile|criteria": 42}

def test_score_none_inputs():
    store = {}
    def compute():
        return 100
    assert score(store, None, "profile", "criteria", compute) == 100
    assert score(store, "text", None, "criteria", compute) == 100
    assert score(store, "text", "profile", None, compute) == 100
    assert score(store, None, None, None, compute) == 100

def test_score_different_inputs():
    store = {}
    def compute():
        return 77
    assert score(store, "text1", "profile1", "criteria1", compute) == 77
    assert score(store, "text2", "profile1", "criteria1", compute) == 77
    assert score(store, "text1", "profile2", "criteria1", compute) == 77
    assert score(store, "text1", "profile1", "criteria2", compute) == 77
